create table public.manila_live_uploads (
 id uuid primary key default gen_random_uuid(), rows jsonb not null,
 parent_id uuid references public.manila_live_uploads(id),
 status text not null default 'draft' check(status in ('draft','published','rolled_back')),
 created_by uuid not null, created_at timestamptz not null default now(), published_at timestamptz
);
alter table public.manila_live_uploads enable row level security;
revoke all on public.manila_live_uploads from public,anon,authenticated;
grant select on public.manila_live_uploads to authenticated;
create policy manila_live_admin_read on public.manila_live_uploads for select to authenticated using((select public.staff_role())='admin');

create function private.validate_manila_live_rows(p_rows jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare r jsonb; prior jsonb; seed jsonb; day date; i integer:=0;
begin
 select rows into seed from private.manila_live_seed limit 1;
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)<jsonb_array_length(seed) or jsonb_array_length(p_rows)>1000 then raise exception 'Invalid weekly series' using errcode='22023';end if;
 for r in select * from jsonb_array_elements(p_rows) loop
  if i<jsonb_array_length(seed) then
   if r is distinct from seed->i then raise exception 'Legacy rows cannot be rewritten; obtain a separately reviewed correction' using errcode='22023';end if;
  else
   if jsonb_typeof(r) is distinct from 'object' or not(r ?& array['week_start','week_end','report_monday','total_since_jan1','weekly_new_cases','total_is_estimate','weekly_is_estimate','note','source_url','observed']) then raise exception 'Missing weekly fields' using errcode='22023';end if;
   if exists(select 1 from jsonb_object_keys(r) k where k not in ('week_start','week_end','report_monday','total_since_jan1','weekly_new_cases','total_is_estimate','weekly_is_estimate','note','source_url','evidence_file','observed','raw_note')) then raise exception 'Unknown weekly field' using errcode='22023';end if;
   if coalesce(r->>'week_start','')!~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(r->>'week_end','')!~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(r->>'report_monday','')!~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid dates' using errcode='22023';end if;
   day:=(r->>'week_start')::date;
   if extract(dow from day)<>1 or (r->>'week_end')::date<>day+6 or (r->>'report_monday')::date<>day+7 or day<>(prior->>'week_start')::date+7 or extract(year from day)<>extract(year from (prior->>'week_start')::date) or (r->>'report_monday')::date>(now() at time zone 'Asia/Manila')::date then raise exception 'Invalid, future, duplicate, gap or year-reset week' using errcode='22023';end if;
   if jsonb_typeof(r->'total_since_jan1') is distinct from 'number' or jsonb_typeof(r->'weekly_new_cases') is distinct from 'number' or coalesce(r->>'total_since_jan1','')!~ '^[0-9]{1,8}$' or coalesce(r->>'weekly_new_cases','')!~ '^[0-9]{1,8}$' or (r->>'total_since_jan1')::bigint>10000000 or (r->>'weekly_new_cases')::bigint>10000000 or (r->>'total_since_jan1')::bigint<(prior->>'total_since_jan1')::bigint or (r->>'weekly_new_cases')::bigint<>(r->>'total_since_jan1')::bigint-(prior->>'total_since_jan1')::bigint then raise exception 'Counts must match cumulative differences' using errcode='22023';end if;
   if jsonb_typeof(r->'total_is_estimate') is distinct from 'boolean' or jsonb_typeof(r->'weekly_is_estimate') is distinct from 'boolean' or jsonb_typeof(r->'observed') is distinct from 'boolean' or (r->>'observed')::boolean=(r->>'weekly_is_estimate')::boolean or (((r->>'total_is_estimate')::boolean or (prior->>'total_is_estimate')::boolean) and not (r->>'weekly_is_estimate')::boolean) then raise exception 'Explicit consistent estimate flags required' using errcode='22023';end if;
   if jsonb_typeof(r->'note') is distinct from 'string' or length(r->>'note')>2000 or (((r->>'total_is_estimate')::boolean or (r->>'weekly_is_estimate')::boolean) and length(trim(r->>'note'))=0) then raise exception 'Estimate note required' using errcode='22023';end if;
   if jsonb_typeof(r->'source_url') is distinct from 'string' or length(r->>'source_url')>2000 or coalesce(r->>'source_url','')!~ '^https://([a-zA-Z0-9-]+\.)*facebook\.com/[^[:space:]]+' or r->>'source_url'~'@' then raise exception 'Public Facebook post URL required' using errcode='22023';end if;
   if r->>'evidence_file' is not null and ((r->>'evidence_file')!~ '^docs/evidence/live-manila/[a-zA-Z0-9_./-]+\.(png|jpg|jpeg|webp|pdf)$' or position('..' in r->>'evidence_file')>0) then raise exception 'Invalid private evidence path' using errcode='22023';end if;
  end if;
  prior:=r;i:=i+1;
 end loop;
end;$$;
revoke all on function private.validate_manila_live_rows(jsonb) from public,anon,authenticated;

create function public.stage_manila_live_upload(p_rows jsonb,p_parent uuid default null) returns uuid
language plpgsql security definer set search_path='' as $$
declare identifier uuid; active_id uuid; active_rows jsonb; count_prior integer;
begin
 if public.staff_role() is distinct from 'admin' then raise exception 'AAL2 admin access required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(20261028);
 select id,rows into active_id,active_rows from public.manila_live_uploads where status='published' order by published_at desc,id desc limit 1;
 if active_id is distinct from p_parent then raise exception 'Published version changed; refresh preview' using errcode='40001';end if;
 if active_rows is null then select rows into active_rows from private.manila_live_seed limit 1;end if;
 perform private.validate_manila_live_rows(p_rows);
 count_prior:=jsonb_array_length(active_rows);
 if jsonb_array_length(p_rows)<=count_prior or exists(select 1 from generate_series(0,count_prior-1) n where p_rows->n is distinct from active_rows->n) then raise exception 'Append only to the current published series' using errcode='22023';end if;
 insert into public.manila_live_uploads(rows,parent_id,created_by) values(p_rows,p_parent,auth.uid()) returning id into identifier;
 insert into public.staff_audit(actor,action,record_id) values(auth.uid(),'stage_manila_live_upload',identifier);
 return identifier;
end;$$;
revoke all on function public.stage_manila_live_upload(jsonb,uuid) from public,anon;
grant execute on function public.stage_manila_live_upload(jsonb,uuid) to authenticated;

create function public.set_manila_live_upload_status(p_id uuid,p_status text) returns void
language plpgsql security definer set search_path='' as $$
declare version public.manila_live_uploads; active_id uuid;
begin
 if public.staff_role() is distinct from 'admin' then raise exception 'AAL2 admin access required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(20261028);
 select * into version from public.manila_live_uploads where id=p_id for update;
 if not found or p_status not in ('published','rolled_back') or not((version.status='draft' and p_status='published') or(version.status='published' and p_status='rolled_back')) then raise exception 'Invalid version transition' using errcode='22023';end if;
 select id into active_id from public.manila_live_uploads where status='published' order by published_at desc,id desc limit 1;
 if p_status='rolled_back' and active_id is distinct from p_id then raise exception 'Only the current publication can be rolled back' using errcode='22023';end if;
 if p_status='published' then
  if active_id is distinct from version.parent_id then raise exception 'Published parent changed; restage' using errcode='40001';end if;
  perform private.validate_manila_live_rows(version.rows);
 end if;
 update public.manila_live_uploads set status=p_status,published_at=case when p_status='published' then clock_timestamp() else published_at end where id=p_id;
 insert into public.staff_audit(actor,action,record_id) values(auth.uid(),'manila_live_'||p_status,p_id);
end;$$;
revoke all on function public.set_manila_live_upload_status(uuid,text) from public,anon;
grant execute on function public.set_manila_live_upload_status(uuid,text) to authenticated;

-- Frozen build-time quantiles/coverage are reused; publication never trains or refits.
-- Generate aggregate JSON on the server so the public UI never invents projection values.
create function private.project_manila_live_rows(p_rows jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare frozen jsonb; counts jsonb; latest jsonb; method jsonb; metadata jsonb; ranges jsonb;
 base integer; lower_count integer; historical_count integer; peak integer;
 observed_counts double precision[]; observed_dates date[]; observed_weeks jsonb;
 rate double precision; tolerance double precision; direction text;
begin
 select payload,complete_counts into frozen,counts from private.manila_live_seed limit 1;
 latest:=p_rows->(jsonb_array_length(p_rows)-1);base:=(latest->>'weekly_new_cases')::integer;
 method:=frozen->'method';metadata:=frozen->'metadata';tolerance:=(method->>'direction_tolerance')::double precision;
 select array_agg((r->>'weekly_new_cases')::double precision order by ordinal),array_agg((r->>'week_end')::date order by ordinal),jsonb_agg(r->>'week_end' order by ordinal)
 into observed_counts,observed_dates,observed_weeks from (
  select r,ordinal from jsonb_array_elements(p_rows) with ordinality x(r,ordinal) where (r->>'observed')::boolean order by ordinal desc limit 3
 ) observed;
 if array_length(observed_counts,1)=3 and observed_counts[1]>0 then rate:=power(observed_counts[3]/observed_counts[1],7.0/(observed_dates[3]-observed_dates[1]))-1;end if;
 direction:=case when rate is null then 'Unavailable' when rate>tolerance then 'Rising' when rate< -tolerance then 'Falling' else 'Steady' end;
 select count(*) filter(where value::integer<base),count(*) into lower_count,historical_count from jsonb_array_elements_text(counts) x(value);
 select max((r->>'weekly_new_cases')::integer) into peak from jsonb_array_elements(p_rows) r;
 select jsonb_agg(jsonb_build_object(
  'horizon',(s->>'horizon')::integer,
  'target_week_start',(latest->>'week_start')::date+7*(s->>'horizon')::integer,
  'target_week_end',(latest->>'week_end')::date+7*(s->>'horizon')::integer,
  'n',(s->>'n')::integer,
  'low',floor(base*(s->'quantiles'->>0)::double precision),
  'median',floor(base*(s->'quantiles'->>1)::double precision+0.5),
  'high',ceil(base*(s->'quantiles'->>2)::double precision),
  'persistence',base) order by (s->>'horizon')::integer)
 into ranges from jsonb_array_elements(method->'sensitivity') s where (s->>'threshold')::integer=100;
 method:=method||jsonb_build_object('ranges',ranges,'direction',direction,'direction_weekly_change',rate,'direction_observed_weeks',coalesce(observed_weeks,'[]'::jsonb),
  'percentile',100.0*lower_count/historical_count,'exceeds_historical_max',base>(method->>'historical_max')::integer,'recent_peak',peak);
 metadata:=metadata||jsonb_build_object('date_range',jsonb_build_array(p_rows->0->>'week_start',latest->>'week_end'),'last_week_end',latest->>'week_end','row_count',jsonb_array_length(p_rows),
  'total_estimate_count',(select count(*) from jsonb_array_elements(p_rows) r where (r->>'total_is_estimate')::boolean),
  'weekly_estimate_count',(select count(*) from jsonb_array_elements(p_rows) r where (r->>'weekly_is_estimate')::boolean),
  'observed_weekly_count',(select count(*) from jsonb_array_elements(p_rows) r where (r->>'observed')::boolean),
  'missing_source_count',(select count(*) from jsonb_array_elements(p_rows) r where r->>'source_url' is null));
 return jsonb_build_object('version',frozen->'version','metadata',metadata,'method',method,'rows',(select jsonb_agg(r-'evidence_file' order by ordinal) from jsonb_array_elements(p_rows) with ordinality x(r,ordinal)));
end;$$;
revoke all on function private.project_manila_live_rows(jsonb) from public,anon,authenticated;

create function public.published_manila_live_input() returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',id,'data',private.project_manila_live_rows(rows),'published_at',published_at)
 from public.manila_live_uploads where status='published' order by published_at desc,id desc limit 1;
$$;
revoke all on function public.published_manila_live_input() from public;
grant execute on function public.published_manila_live_input() to anon,authenticated;
